Reference implementation (Python 3.12+):
```python
from collections import Counter

def unique_permutations(values):
    counts=Counter(values); path=[]; result=[]
    def visit():
        if len(path) == len(values): result.append(tuple(path)); return
        for value in counts:
            if counts[value] == 0: continue
            counts[value]-=1; path.append(value); visit(); path.pop(); counts[value]+=1
    visit(); return result

assert set(unique_permutations([1,1,2])) == {(1,1,2),(1,2,1),(2,1,1)}
